query MexFetchAllSubgroupsJobQuery($group_id, $query_context, $sub_group_hint_id) {
  id
  __typename
  value
  creation_time
  subject {
    properties {
      general_chat
      membership_approval_mode_enabled
      hidden_group
      membership_approval_requests {
        total_count
        subject {
          xwa2_group_query_by_id {
            default_sub_group {
              sub_groups {
                edges {
                  node {
                    xwa2_group_query_by_id {
                      default_sub_group {
                        sub_groups {
                          edges {
                            node {
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
